static void stored(istate *s)
{
    s->bitbuf = 0; s->bitcnt = 0;
    if (s->inpos + 4 > s->inlen) { s->error = 1; return; }
    unsigned int len = s->in[s->inpos] | (s->in[s->inpos + 1] << 8);
    unsigned int nlen = s->in[s->inpos + 2] | (s->in[s->inpos + 3] << 8);
    s->inpos += 4;
    if ((len ^ 0xffff) != nlen) { s->error = 1; return; }
    if (s->inpos + len > s->inlen) { s->error = 1; return; }
    for (unsigned int i = 0; i < len; i++) putbyte(s, s->in[s->inpos++]);
}

static void fixed(istate *s)
{
    static huff lencode, distcode;
    static int built = 0;
    if (!built) {
        unsigned char lengths[320];
        int i;
        for (i = 0; i < 144; i++) lengths[i] = 8;
        for (; i < 256; i++) lengths[i] = 9;
        for (; i < 280; i++) lengths[i] = 7;
        for (; i < 288; i++) lengths[i] = 8;
        build(&lencode, lengths, 288);
        for (i = 0; i < 30; i++) lengths[i] = 5;
        build(&distcode, lengths, 30);
        built = 1;
    }
    codes(s, &lencode, &distcode);
}

static void dynamic(istate *s)
{
    static const unsigned char order[19] = {16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};
    unsigned char lengths[320];
    huff lencode, distcode;
    int nlen = (int)getbits(s, 5) + 257;
    int ndist = (int)getbits(s, 5) + 1;
    int ncode = (int)getbits(s, 4) + 4;
    if (s->error) return;
    if (nlen > 286 || ndist > 30) { s->error = 1; return; }
    int i;
    for (i = 0; i < ncode; i++) lengths[order[i]] = (unsigned char)getbits(s, 3);
    for (; i < 19; i++) lengths[order[i]] = 0;
    build(&lencode, lengths, 19);
    i = 0;
    while (i < nlen + ndist) {
        int sym = decode(s, &lencode);
        if (s->error) return;
        if (sym < 16) {
            lengths[i++] = (unsigned char)sym;
        } else {
            int len = 0, rep;
            if (sym == 16) {
                if (i == 0) { s->error = 1; return; }
                len = lengths[i - 1];
                rep = 3 + (int)getbits(s, 2);
            } else if (sym == 17) {
                rep = 3 + (int)getbits(s, 3);
            } else {
                rep = 11 + (int)getbits(s, 7);
            }
            if (i + rep > nlen + ndist) { s->error = 1; return; }
            while (rep--) lengths[i++] = (unsigned char)len;
        }
    }
    build(&lencode, lengths, nlen);
    build(&distcode, lengths + nlen, ndist);
    codes(s, &lencode, &distcode);
}

unsigned char *inflate_raw(const unsigned char *in, size_t inlen, size_t *outlen, int *err)
{
    istate s;
    memset(&s, 0, sizeof(s));
    s.in = in; s.inlen = inlen;
    int last;
    do {
        last = getbit(&s);
        int type = (int)getbits(&s, 2);
        if (s.error) break;
        if (type == 0) stored(&s);
        else if (type == 1) fixed(&s);
        else if (type == 2) dynamic(&s);
        else s.error = 1;
    } while (!last && !s.error);
    *err = s.error;
    *outlen = s.outlen;
    return s.out;
}
