    if (c == '-') { sign = 1; c = Zgetc(fp); }
    else if (c == '+') { c = Zgetc(fp); }

    if (c == '0') {
        gotdigits = 1;
        c = Zgetc(fp);
        if (c == 'x' || c == 'X') {
            base = 16;
            c = Zgetc(fp);
