    next = Zgetc(fp);
    switch (next) {
    case 'a': return 7;
    case 'b': return 8;
    case 'e': return 27;
    case 'f': return 12;
    case 'n': return 10;
    case 'r': return 13;
    case 't': return 9;
    case 'v': return 11;
    default:
        if (next == '-' || next == 'x' || (next >= '0' && next <= '9')) {
