/* emulate sscanf("%*c%c %d %d %d %d %d %d %d") */
static int parseheader(const char *line, char *hb, int *nums, int maxnums)
{
    const char *p = line;
    int count = 0;
    if (!*p) return 0;
    p++;                       /* %*c */
    if (!*p) return 0;
    *hb = *p++;                /* %c */
    count = 0;
    while (count < maxnums) {
        while (*p && isspace((unsigned char)*p)) p++;
        const char *q = p;
        int neg = 0;
        if (*q == '-' || *q == '+') { neg = (*q == '-'); q++; }
        if (!(*q >= '0' && *q <= '9')) break;
        long v = 0;
        while (*q >= '0' && *q <= '9') { v = v * 10 + (*q - '0'); q++; }
        nums[count++] = (int)(neg ? -v : v);
        p = q;
    }
    return count + 1;
}

static void readfont(void)
{
    ZFILE *fontfile = NULL;
    char *fontpath;
    char magic[5];
    char fileline[MAXLEN + 2];
    char hb = 0;
    int nums[7] = {0, 0, 0, 0, 0, 0, 0};
    int numsread, i;
    int upheight, maxlen, smush, cmtlines, ffright2left, smush2;
    inchr theord;

    fontpath = myalloc(strlen(fontdirname) + strlen(fontname) + 16);
    if (!hasdirsep(fontname)) {
        sprintf(fontpath, "%s/%s.flf", fontdirname, fontname);
        fontfile = Zopen(fontpath);
    }
    if (!fontfile) {
        sprintf(fontpath, "%s.flf", fontname);
        fontfile = Zopen(fontpath);
    }
    if (!fontfile) {
        toiletfont = 1;
        if (!hasdirsep(fontname)) {
            sprintf(fontpath, "%s/%s.tlf", fontdirname, fontname);
            fontfile = Zopen(fontpath);
        }
        if (!fontfile) {
            sprintf(fontpath, "%s.tlf", fontname);
            fontfile = Zopen(fontpath);
        }
    }
    if (!fontfile) {
        fprintf(stderr, "%s: %s: Unable to open font file\n", myname, fontname);
        exit(1);
    }
    free(fontpath);

    for (i = 0; i < 4; i++) {
        int c = Zgetc(fontfile);
        magic[i] = (c == EOF) ? 0 : (char)c;
    }
    magic[4] = 0;
    if (myfgets(fileline, MAXLEN + 1, fontfile) == NULL)
        fileline[0] = '\0';
    if (strlen(fileline) > 0 && fileline[strlen(fileline) - 1] != '\n')
        skiptoeol(fontfile);
    numsread = parseheader(fileline, &hb, nums, 7);
    charheight = nums[0];
    upheight = nums[1];
    maxlen = nums[2];
    smush = nums[3];
    cmtlines = nums[4];
    ffright2left = nums[5];
    smush2 = nums[6];
    (void)upheight;

    if (numsread >= 4 && maxlen > MAXLEN) {
        fprintf(stderr, "%s: %s: character is too wide\n", myname, fontname);
        exit(1);
    }
    if (strcmp(magic, toiletfont ? "tlf2" : "flf2") != 0 || numsread < 6) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", myname, fontname);
        exit(1);
    }
    hardblank = hb;
    for (i = 1; i <= cmtlines; i++) skiptoeol(fontfile);

    if (numsread < 7) ffright2left = 0;
    if (numsread < 8) {
        if (smush == 0) smush2 = SM_KERN;
        else if (smush < 0) smush2 = 0;
        else smush2 = (smush & 31) | SM_SMUSH;
    }
    if (charheight < 1) charheight = 1;

    if (smushoverride == SMO_NO) smushmode = smush2;
    else if (smushoverride == SMO_FORCE) smushmode |= smush2;

    if (right2left < 0) right2left = ffright2left;
    if (justification < 0) justification = 2 * right2left;

    /* the implicit empty character 0 */
    {
        outchr **rows = myalloc(sizeof(outchr *) * charheight);
        for (i = 0; i < charheight; i++) {
            rows[i] = myalloc(sizeof(outchr));
            rows[i][0] = 0;
        }
        storechar(0, rows);
    }
    memset(decodebuf, 0, sizeof(decodebuf));

    for (theord = ' '; theord <= '~'; theord++)
        readfontchar(fontfile, theord);
    for (i = 0; i < 7; i++)
        readfontchar(fontfile, deutsch[i]);
    while (readnum(fontfile, &theord)) {
        skiptoeol(fontfile);
        readfontchar(fontfile, theord);
    }
    Zclose(fontfile);
}

/* ------------------------------------------------------------------ */
/* Output line handling                                                 */

static void linealloc(void)
{
    int row;
    outputline = myalloc(sizeof(outchr *) * charheight);
    for (row = 0; row < charheight; row++) {
        outputline[row] = myalloc(sizeof(outchr) * (outlinelenlimit + MAXLEN + 2));
        outputline[row][0] = 0;
    }
    inchrlinelenlimit = outputwidth * 4 + 100;
    inchrline = myalloc(sizeof(inchr) * (inchrlinelenlimit + 2));
    outlinelen = 0;
    inchrlinelen = 0;
}

static void clearline(void)
{
    int i;
    for (i = 0; i < charheight; i++) outputline[i][0] = 0;
    outlinelen = 0;
    inchrlinelen = 0;
}

static void putwchar_utf8(long c)
{
    unsigned char buf[8];
    int n = 0;
    if (c < 0) c = (long)(unsigned int)c;
    if (c < 0x80) { putchar((int)c); return; }
    if (c < 0x800) { buf[0] = 0xC0 | (c >> 6); n = 2; }
    else if (c < 0x10000) { buf[0] = 0xE0 | (c >> 12); n = 3; }
    else if (c < 0x200000) { buf[0] = 0xF0 | (c >> 18); n = 4; }
    else if (c < 0x4000000) { buf[0] = 0xF8 | (c >> 24); n = 5; }
    else { buf[0] = 0xFC | ((c >> 30) & 1); n = 6; }
    for (int i = n - 1; i >= 1; i--) {
        buf[i] = 0x80 | (c & 0x3F);
        c >>= 6;
    }
    fwrite(buf, 1, n, stdout);
}

static void putstring(outchr *string)
{
    int i, len;
    len = ostrlen(string);
    if (outputwidth > 1) {
        if (len > outputwidth - 1) {
            if (right2left) string += len - (outputwidth - 1);
            len = outputwidth - 1;
        }
        if (justification > 0) {
            for (i = 1; (3 - justification) * i + len + justification - 2 < outputwidth; i++)
                putchar(' ');
        }
    }
    for (i = 0; i < len; i++) putwchar_utf8(string[i]);
    putchar('\n');
}

static void printline(void)
{
    int i, j;
    for (i = 0; i < charheight; i++) {
        for (j = 0; outputline[i][j]; j++)
            if (outputline[i][j] == hardblank) outputline[i][j] = ' ';
        putstring(outputline[i]);
    }
    clearline();
}

/* ------------------------------------------------------------------ */
/* Smushing                                                             */

static outchr smushem(outchr lch, outchr rch)
{
    if (lch == ' ') return rch;
    if (rch == ' ') return lch;
    if (previouscharwidth < 2 || currcharwidth < 2) return 0;
    if ((smushmode & SM_SMUSH) == 0) return 0;

    if ((smushmode & 63) == 0) {
        if (lch == ' ') return rch;
        if (rch == ' ') return lch;
        if (lch == hardblank) return rch;
        if (rch == hardblank) return lch;
        if (right2left) return lch;
        return rch;
    }

    if (smushmode & SM_HARDBLANK) {
        if (lch == hardblank && rch == hardblank) return lch;
    }
    if (lch == hardblank || rch == hardblank) return 0;

    if (smushmode & SM_EQUAL) {
        if (lch == rch) return lch;
    }
    if (smushmode & SM_LOWLINE) {
        if (lch == '_' && rch < 128 && rch > 0 && strchr("|/\\[]{}()<>", rch)) return rch;
        if (rch == '_' && lch < 128 && lch > 0 && strchr("|/\\[]{}()<>", lch)) return lch;
    }
    if (smushmode & SM_HIERARCHY) {
        int l = (lch > 0 && lch < 128) ? lch : 0;
        int r = (rch > 0 && rch < 128) ? rch : 0;
        if (l == '|' && r && strchr("/\\[]{}()<>", r)) return rch;
        if (r == '|' && l && strchr("/\\[]{}()<>", l)) return lch;
        if (l && strchr("/\\", l) && r && strchr("[]{}()<>", r)) return rch;
        if (r && strchr("/\\", r) && l && strchr("[]{}()<>", l)) return lch;
        if (l && strchr("[]", l) && r && strchr("{}()<>", r)) return rch;
        if (r && strchr("[]", r) && l && strchr("{}()<>", l)) return lch;
        if (l && strchr("{}", l) && r && strchr("()<>", r)) return rch;
        if (r && strchr("{}", r) && l && strchr("()<>", l)) return lch;
        if (l && strchr("()", l) && r && strchr("<>", r)) return rch;
        if (r && strchr("()", r) && l && strchr("<>", l)) return lch;
    }
    if (smushmode & SM_PAIR) {
        if (lch == '[' && rch == ']') return '|';
        if (rch == '[' && lch == ']') return '|';
        if (lch == '{' && rch == '}') return '|';
        if (rch == '{' && lch == '}') return '|';
        if (lch == '(' && rch == ')') return '|';
        if (rch == '(' && lch == ')') return '|';
    }
    if (smushmode & SM_BIGX) {
        if (lch == '/' && rch == '\\') return '|';
        if (rch == '/' && lch == '\\') return 'Y';
        if (lch == '>' && rch == '<') return 'X';
    }
    return 0;
}

static void getletter(inchr c)
{
    outchr **ch = findchar(c);
    if (!ch) ch = findchar(0);
    currchar = ch;
    previouscharwidth = currcharwidth;
    currcharwidth = ostrlen(currchar[0]);
}

static int smushamt(void)
{
    int maxsmush, amt, row, linebd, charbd;
    outchr ch1, ch2;

    if ((smushmode & (SM_SMUSH | SM_KERN)) == 0) return 0;
    maxsmush = currcharwidth;
    for (row = 0; row < charheight; row++) {
        if (right2left) {
            int ll = ostrlen(outputline[row]);
            if (maxsmush > ll) maxsmush = ll;
            for (charbd = ostrlen(currchar[row]);
                 ch1 = currchar[row][charbd], (charbd > 0 && (!ch1 || ch1 == ' '));
                 charbd--) ;
            for (linebd = 0; ch2 = outputline[row][linebd], ch2 == ' '; linebd++) ;
            amt = linebd + currcharwidth - 1 - charbd;
        } else {
            for (linebd = ostrlen(outputline[row]);
                 ch1 = outputline[row][linebd], (linebd > 0 && (!ch1 || ch1 == ' '));
                 linebd--) ;
            for (charbd = 0; ch2 = currchar[row][charbd], ch2 == ' '; charbd++) ;
            amt = charbd + outlinelen - 1 - linebd;
        }
        if (!ch1 || ch1 == ' ') amt++;
        else if (ch2) {
            if (smushem(ch1, ch2) != 0) amt++;
        }
        if (amt < maxsmush) maxsmush = amt;
    }
    return maxsmush;
}

static outchr *templine;

/* append the current character to the line with the given smush amount */
static void placechar(int smushamount)
{
    int row, k, column;
    for (row = 0; row < charheight; row++) {
        if (right2left) {
            ocopy(templine, currchar[row]);
            for (k = 0; k < smushamount; k++) {
                templine[currcharwidth - smushamount + k] =
                    smushem(templine[currcharwidth - smushamount + k], outputline[row][k]);
            }
            ocat(templine, outputline[row] + smushamount);
            ocopy(outputline[row], templine);
        } else {
            for (k = 0; k < smushamount; k++) {
                column = outlinelen - smushamount + k;
                if (column < 0) column = 0;
                outputline[row][column] = smushem(outputline[row][column], currchar[row][k]);
            }
            ocat(outputline[row], currchar[row] + smushamount);
        }
    }
    outlinelen = ostrlen(outputline[0]);
}

static int addchar(inchr c)
{
    int smushamount;
    getletter(c);
    smushamount = smushamt();
    if (outlinelen + currcharwidth - smushamount > outlinelenlimit
        || inchrlinelen + 1 > inchrlinelenlimit) {
        return 0;
    }
    placechar(smushamount);
    if (inchrlinelen < inchrlinelenlimit + 1)
        inchrline[inchrlinelen++] = c;
    return 1;
}

/* add a character that does not fit on an empty line, unsmushed */
static void forcechar(inchr c)
{
    getletter(c);
    placechar(0);
    if (inchrlinelen < inchrlinelenlimit + 1)
        inchrline[inchrlinelen++] = c;
}

static void splitline(void)
{
    int i, gotspace, lastspace = -1, len1, len2;
    inchr *part1, *part2;

    part1 = myalloc(sizeof(inchr) * (inchrlinelen + 1));
    part2 = myalloc(sizeof(inchr) * (inchrlinelen + 1));
    gotspace = 0;
    for (i = inchrlinelen - 1; i >= 0; i--) {
        if (!gotspace && inchrline[i] == ' ') {
            gotspace = 1;
            lastspace = i;
        }
        if (gotspace && inchrline[i] != ' ') break;
    }
    if (!gotspace) {
        /* no break point: behave like a plain line flush */
        free(part1); free(part2);
        printline();
        return;
    }
    len1 = i + 1;
    len2 = inchrlinelen - lastspace - 1;
    for (i = 0; i < len1; i++) part1[i] = inchrline[i];
    for (i = 0; i < len2; i++) part2[i] = inchrline[lastspace + 1 + i];
    clearline();
    for (i = 0; i < len1; i++) addchar(part1[i]);
    printline();
    for (i = 0; i < len2; i++) addchar(part2[i]);
    free(part1);
    free(part2);
}

/* ------------------------------------------------------------------ */
/* Input                                                                */

static int readbyte(void)
{
    if (cmdinput) {
        for (;;) {
            if (cmdwordidx >= cmdwordcount) return EOF;
            if (*cmdptr) return (unsigned char)*cmdptr++;
            /* word exhausted */
            int wasempty = (cmdwords[cmdwordidx][0] == '\0');
            cmdwordidx++;
            if (cmdwordidx >= cmdwordcount) return EOF;
            cmdptr = cmdwords[cmdwordidx];
            return wasempty ? '\n' : ' ';
        }
    }
    return getchar();
}

static inchr iso2022(void)
{
    inchr ch, ch2;
    int save_gl, save_gr;

    ch = readbyte();
    if (ch == EOF) return ch;
    if (ch == 27) ch = readbyte() + 0x100;
    if (ch == 0x100 + '$') ch = readbyte() + 0x200;
    switch (ch) {
    case 14: gl = 1; return iso2022();
    case 15: gl = 0; return iso2022();
    case 142: case 0x100 + 'N':
        save_gl = gl; save_gr = gr; gl = gr = 2;
        ch = iso2022();
        gl = save_gl; gr = save_gr;
        return ch;
    case 143: case 0x100 + 'O':
        save_gl = gl; save_gr = gr; gl = gr = 3;
        ch = iso2022();
        gl = save_gl; gr = save_gr;
        return ch;
    case 0x100 + 'n': gl = 2; return iso2022();
    case 0x100 + 'o': gl = 3; return iso2022();
    case 0x100 + '~': gr = 1; return iso2022();
    case 0x100 + '}': gr = 2; return iso2022();
    case 0x100 + '|': gr = 3; return iso2022();
    case 0x100 + '(': case 0x100 + ')': case 0x100 + '*': case 0x100 + '+': {
        int n = (int)(ch - (0x100 + '('));
        ch2 = readbyte();
        if (ch2 == 'B') ch2 = 0;
        gn[n] = ch2 << 16;
        gndbl[n] = 0;
        return iso2022();
    }
    case 0x100 + '-': case 0x100 + '.': case 0x100 + '/': {
        int n = (int)(ch - (0x100 + '-')) + 1;
        ch2 = readbyte();
        if (ch2 == 'A') gn[n] = 0x80;
        else gn[n] = (ch2 << 16) | 0x80;
        gndbl[n] = 0;
        return iso2022();
    }
    case 0x200 + '(': case 0x200 + ')': case 0x200 + '*': case 0x200 + '+': {
        int n = (int)(ch - (0x200 + '('));
        ch2 = readbyte();
        gn[n] = ch2 << 16;
        gndbl[n] = 1;
        return iso2022();
    }
    default:
        break;
    }
    if (ch >= 0x200 && ch < 0x300) {
        /* ESC $ F : obsolete designation of a 94x94 set into G0 */
        gn[0] = (ch - 0x200) << 16;
        gndbl[0] = 1;
        return iso2022();
    }
    if (ch >= 0x21 && ch <= 0x7E) {
        if (gl >= 0 && gl < 4) {
            if (gndbl[gl]) {
                ch2 = readbyte();
                ch = gn[gl] | (ch << 8) | ch2;
            } else {
                ch = gn[gl] | ch;
            }
        }
    } else if (ch >= 0xA0 && ch <= 0xFF) {
        if (gr >= 0 && gr < 4) {
            if (gndbl[gr]) {
                ch2 = readbyte();
                ch = gn[gr] | (ch << 8) | ch2;
            } else {
                ch = gn[gr] | (ch & 0x7F);
            }
        }
    }
    return ch;
}

static inchr getinchr_raw(void)
{
    int c, c2, n, i;
    inchr ch;

    switch (multibyte) {
    case 0:
        return iso2022();
    case 1: case 4:
        c = readbyte();
        if ((c >= 0x80 && c <= 0x9f) || (c >= 0xe0 && c <= 0xef)) {
            c2 = readbyte();
            return ((inchr)c << 8) + c2;
        }
        return c;
    case 2:
        c = readbyte();
        if (c == EOF) return EOF;
        if (c < 0x80) return c;
        if (c < 0xC0 || c >= 0xFE) return 0x80;
        if (c < 0xE0) { n = 1; ch = c & 0x1F; }
        else if (c < 0xF0) { n = 2; ch = c & 0x0F; }
        else if (c < 0xF8) { n = 3; ch = c & 0x07; }
        else if (c < 0xFC) { n = 4; ch = c & 0x03; }
        else { n = 5; ch = c & 0x01; }
        for (i = 0; i < n; i++) {
            c2 = readbyte();
            ch = (ch << 6) | (c2 & 0x3F);
        }
        return ch;
    case 3:
        c = readbyte();
        if (c == EOF) return EOF;
        if (hzmode) {
            c2 = readbyte();
            return ((inchr)c << 8) + c2;
        }
        if (c == '~') {
            c2 = readbyte();
            if (c2 == '{') { hzmode = 1; return getinchr_raw(); }
            if (c2 == '~') return '~';
            return getinchr_raw();
        }
        return c;
    }
    return EOF;
}

static int ungot_valid = 0;
static inchr ungot_char;

static inchr getinchr(void)
{
    if (ungot_valid) {
        ungot_valid = 0;
        return ungot_char;
    }
    return getinchr_raw();
}

static void ungetinchr(inchr c)
{
    ungot_valid = 1;
    ungot_char = c;
}

/* ------------------------------------------------------------------ */
/* Parameters                                                           */

static char *stripsuffix(const char *name, const char *suffix)
{
    char *s = myalloc(strlen(name) + 1);
    strcpy(s, name);
    if (suffixcmp(s, suffix)) s[strlen(s) - strlen(suffix)] = 0;
    return s;
}

static void getparams(int argc, char *argv[])
{
    extern char *optarg;
    extern int optind;
    int c, columns;
    char *env;

    myname = strrchr(argv[0], '/');
    myname = myname ? myname + 1 : argv[0];

    env = getenv("FIGLET_FONTDIR");
    fontdirname = env ? env : DEFAULT_FONTDIR;
    fontname = DEFAULT_FONT;

    while ((c = getopt(argc, argv, "ADEXLRI:xlcrpntvm:w:d:f:C:NFskSWo")) != -1) {
        switch (c) {
        case 'A':
            break;
        case 'D': deutschflag = 1; break;
        case 'E': deutschflag = 0; break;
        case 'X': right2left = -1; break;
        case 'L': right2left = 0; break;
        case 'R': right2left = 1; break;
        case 'x': justification = -1; break;
        case 'l': justification = 0; break;
        case 'c': justification = 1; break;
        case 'r': justification = 2; break;
        case 'p': paragraphflag = 1; break;
        case 'n': paragraphflag = 0; break;
        case 's': smushoverride = SMO_NO; break;
        case 'k': smushmode = SM_KERN; smushoverride = SMO_YES; break;
        case 'S': smushmode = SM_SMUSH; smushoverride = SMO_FORCE; break;
        case 'W': smushmode = 0; smushoverride = SMO_YES; break;
        case 'o': smushmode = SM_SMUSH; smushoverride = SMO_YES; break;
        case 'm':
            smushmode = atoi(optarg);
            if (smushmode < -1) {
                smushoverride = SMO_NO;
                break;
            }
            if (smushmode == 0) smushmode = SM_KERN;
            else if (smushmode == -1) smushmode = 0;
            else smushmode = (smushmode & 63) | SM_SMUSH;
            smushoverride = SMO_YES;
            break;
        case 't': {
            int fd = open("/dev/tty", O_RDONLY | O_NOCTTY);
            if (fd >= 0) {
                struct winsize ws;
                if (ioctl(fd, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0)
                    outputwidth = ws.ws_col;
                close(fd);
            }
            break;
        }
        case 'v': infoprint = 0; break;
        case 'I': infoprint = atoi(optarg); break;
        case 'w':
            columns = atoi(optarg);
            if (columns > 0) outputwidth = columns;
            break;
        case 'd':
            fontdirname = optarg;
            break;
        case 'f': {
            char *s = stripsuffix(optarg, ".flf");
            if (strcmp(s, optarg) == 0) {
                free(s);
                s = stripsuffix(optarg, ".tlf");
            }
            fontname = s;
            break;
        }
        case 'C': {
            cfnamenode *n = myalloc(sizeof(cfnamenode));
            n->thename = stripsuffix(optarg, ".flc");
            n->next = NULL;
            *cfilelistend = n;
            cfilelistend = &n->next;
            break;
        }
        case 'N':
            cfilelist = NULL;
            cfilelistend = &cfilelist;
            break;
        case 'F':
            fprintf(stderr, "%s: illegal option -- F\n", myname);
            printusage(stderr);
            fprintf(stderr, "\nBecause of numerous incompatibilities, the \"-F\" option has been\n");
            fprintf(stderr, "removed.  It has been replaced by the \"figlist\" program, which is now\n");
            fprintf(stderr, "included in the basic FIGlet package.  \"figlist\" is also available\n");
            fprintf(stderr, "from  http://www.figlet.org/under UNIX utilities.\n");
            exit(1);
        default:
            printusage(stderr);
            exit(1);
        }
    }
    if (optind < argc) {
        cmdinput = 1;
        cmdwords = argv + optind;
        cmdwordcount = argc - optind;
        cmdwordidx = 0;
        cmdptr = cmdwords[0];
    } else {
        cmdinput = 0;
    }
    outlinelenlimit = outputwidth - 1;
    if (infoprint >= 0) {
        printinfo(infoprint);
        exit(0);
    }
}

/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    inchr c, c2;
    int last_was_eol_flag = 0;
    int wordbreakmode = 0;
    int charnotadded;

    getparams(argc, argv);
    readcontrolfiles();
    readfont();
    linealloc();
    templine = myalloc(sizeof(outchr) * (outlinelenlimit + 2 * MAXLEN + 4));

    while ((c = getinchr()) != EOF) {

        if (c == '\n' && paragraphflag && !last_was_eol_flag) {
            ungetinchr(c2 = getinchr());
            c = ((c2 >= 0 && c2 < 128 && isspace((int)c2)) ? '\n' : ' ');
        }
        last_was_eol_flag = (c >= 0 && c < 128 && isspace((int)c) && c != '\t' && c != ' ');

        if (deutschflag) {
            if (c >= '[' && c <= ']') c = deutsch[c - '['];
            else if (c >= '{' && c <= '~') c = deutsch[c - '{' + 3];
        }

        c = handlemapping(c);

        if (c >= 0 && c < 128 && isspace((int)c))
            c = (c == '\t' || c == ' ') ? ' ' : '\n';

        if ((c > 0 && c < ' ' && c != '\n') || c == 127) continue;

        if (wordbreakmode == -1) {
            if (c == ' ') continue;
            if (c == '\n') { wordbreakmode = 0; continue; }
        }

        if (c == '\n') {
            printline();
            wordbreakmode = 0;
            continue;
        }

        do {
            charnotadded = !addchar(c);
            if (charnotadded) {
                if (outlinelen == 0) {
                    /* too wide for an empty line: place it anyway */
                    forcechar(c);
                    charnotadded = 0;
                    if (wordbreakmode == -1) wordbreakmode = 0;
                    wordbreakmode = (wordbreakmode >= 2) ? 1 : wordbreakmode;
                    if (c != ' ' && wordbreakmode == 0) wordbreakmode = 1;
                } else if (c == ' ') {
                    if (wordbreakmode == 2) splitline();
                    else printline();
                    wordbreakmode = -1;
                    charnotadded = 0;
                } else {
                    if (wordbreakmode >= 2) splitline();
                    else printline();
                    wordbreakmode = (wordbreakmode == 3) ? 1 : 0;
                }
            } else if (c == ' ') {
                wordbreakmode = (wordbreakmode > 0) ? 2 : 0;
            } else {
                wordbreakmode = (wordbreakmode >= 2) ? 3 : 1;
            }
        } while (charnotadded);
    }

    if (outlinelen != 0) printline();
    return 0;
}
