    size_t pos;
    int ungot;      /* number of pushed-back chars (0 or 1) */
    int ungotc;
} ZFILE;

static unsigned char *slurp(const char *path, size_t *len)
{
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    size_t cap = 65536, n = 0;
    unsigned char *buf = malloc(cap);
    if (!buf) { fclose(f); return NULL; }
    for (;;) {
        if (n == cap) {
            cap *= 2;
            unsigned char *nb = realloc(buf, cap);
            if (!nb) { free(buf); fclose(f); return NULL; }
            buf = nb;
        }
        size_t r = fread(buf + n, 1, cap - n, f);
        if (r == 0) break;
        n += r;
    }
    fclose(f);
    *len = n;
    return buf;
}

static unsigned int rd16(const unsigned char *p) { return p[0] | (p[1] << 8); }
static unsigned int rd32(const unsigned char *p) { return p[0] | (p[1] << 8) | ((unsigned)p[2] << 16) | ((unsigned)p[3] << 24); }

static ZFILE *Zopen(const char *path)
{
    size_t len;
    unsigned char *data = slurp(path, &len);
    if (!data) return NULL;
    ZFILE *z = calloc(1, sizeof(ZFILE));
    z->data = data; z->len = len;
    if (len >= 30 && data[0] == 'P' && data[1] == 'K' && data[2] == 3 && data[3] == 4) {
        unsigned int method = rd16(data + 8);
        unsigned int usize = rd32(data + 22);
        unsigned int namelen = rd16(data + 26);
        unsigned int extralen = rd16(data + 28);
        size_t start = 30 + namelen + extralen;
        if (method == 8 && start <= len) {
            size_t outlen; int err;
            unsigned char *out = inflate_raw(data + start, len - start, &outlen, &err);
            if (!err && out && outlen == usize) {
                free(data);
                z->data = out; z->len = outlen;
            } else {
                free(out);
            }
        }
    }
    return z;
}

static void Zclose(ZFILE *z)
{
    if (!z) return;
    free(z->data);
    free(z);
}

static int Zgetc(ZFILE *z)
{
    if (z->ungot) { z->ungot = 0; return z->ungotc; }
    if (z->pos >= z->len) return EOF;
