/* ------------------------------------------------------------------ */
/* Low level file helpers                                               */

static void crash_like_original(void)
{
    /* The reference implementation dereferences an invalid pointer in
       this situation.  Mirror the visible effect. */
    fflush(stdout);
    raise(SIGSEGV);
    _exit(139);
}

static void skiptoeol(ZFILE *fp)
{
    int c;
    while ((c = Zgetc(fp)) != EOF) {
        if (c == '\n') return;
    }
}

static void skipws(ZFILE *fp)
{
    int c;
    while ((c = Zgetc(fp)) != EOF && c < 128 && isspace(c)) ;
    if (c == EOF) crash_like_original();
    Zungetc(c, fp);
}

static int readnum(ZFILE *fp, inchr *nump)
{
    int c;
    int sign = 0;
    int acc = 0;
    int base = 10;
    int gotdigits = 0;

    do {
        c = Zgetc(fp);
    } while (c != EOF && c < 128 && isspace(c) && c != '\n' && c != '\r');

    if (c == '-') { sign = 1; c = Zgetc(fp); }
    else if (c == '+') { c = Zgetc(fp); }

    if (c == '0') {
        gotdigits = 1;
        c = Zgetc(fp);
        if (c == 'x' || c == 'X') {
            base = 16;
            c = Zgetc(fp);
        } else {
            base = 8;
        }
    }
    for (;;) {
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else break;
        if (d >= base) break;
        acc = (int)((unsigned int)acc * (unsigned int)base + (unsigned int)d);
        gotdigits = 1;
        c = Zgetc(fp);
    }
    Zungetc(c, fp);
    if (sign) acc = (int)(0u - (unsigned int)acc);
    *nump = acc;
    return gotdigits;
}

static inchr readTchar(ZFILE *fp)
{
    int thechar, next;
    inchr num;

    thechar = Zgetc(fp);
    if (thechar == '\n' || thechar == '\r') {
        Zungetc(thechar, fp);
        return 0;
    }
    if (thechar != '\\') return thechar;
    next = Zgetc(fp);
    switch (next) {
    case 'a': return 7;
    case 'b': return 8;
    case 'e': return 27;
    case 'f': return 12;
    case 'n': return 10;
    case 'r': return 13;
    case 't': return 9;
    case 'v': return 11;
    default:
        if (next == '-' || next == 'x' || (next >= '0' && next <= '9')) {
            Zungetc(next, fp);
            readnum(fp, &num);
            return num;
        }
        return next;
    }
}

/* read a line of at most maxlen bytes (including newline) */
static char *myfgets(char *line, int maxlen, ZFILE *fp)
{
    int c = 0;
    char *p = line;
    while (maxlen > 0 && (c = Zgetc(fp)) != EOF) {
        *p++ = (char)c;
        maxlen--;
        if (c == '\n') break;
    }
    *p = 0;
    if (c == EOF) return NULL;
    return line;
}

/* ------------------------------------------------------------------ */
/* Control files                                                        */

static void addcommand(int cmd, inchr lo, inchr hi, int offset)
{
    comnode *n = myalloc(sizeof(comnode));
    n->thecommand = cmd;
    n->rangelo = lo;
    n->rangehi = hi;
    n->offset = offset;
    n->next = NULL;
    *commandlistend = n;
    commandlistend = &n->next;
}

static void charset(int n, ZFILE *fp)
{
    int c;
    skipws(fp);
    if (Zgetc(fp) != '9') {
        skiptoeol(fp);
        return;
    }
    c = Zgetc(fp);
    if (c == '4') {
        c = Zgetc(fp);
        if (c == 'x') {
            /* 94x94 double byte set: skip the "94" */
            Zgetc(fp);
            Zgetc(fp);
            skipws(fp);
            c = Zgetc(fp);
            gn[n] = (inchr)c << 16;
            gndbl[n] = 1;
        } else {
            Zungetc(c, fp);
            skipws(fp);
            c = Zgetc(fp);
            gn[n] = (inchr)c << 16;
            gndbl[n] = 0;
        }
    } else if (c == '6') {
        c = Zgetc(fp);
        gn[n] = ((inchr)c << 16) | 0x80;
        gndbl[n] = 0;
    }
    skiptoeol(fp);
}

static void readcontrol(const char *controlname)
{
    ZFILE *fp = NULL;
    char *path;
    inchr firstch, lastch, target;
    int command, dashcheck;

    path = myalloc(strlen(fontdirname) + strlen(controlname) + 16);
    if (!hasdirsep(controlname)) {
        sprintf(path, "%s/%s.flc", fontdirname, controlname);
        fp = Zopen(path);
    }
    if (!fp) {
        sprintf(path, "%s.flc", controlname);
        fp = Zopen(path);
    }
    if (!fp) {
        fprintf(stderr, "%s: %s: Unable to open control file\n", myname, controlname);
        exit(1);
    }
    free(path);

    addcommand(0, 0, 0, 0); /* begin with a freeze */

    while ((command = Zgetc(fp)) != EOF) {
        switch (command) {
        case 't':
            skipws(fp);
            firstch = readTchar(fp);
            dashcheck = Zgetc(fp);
            if (dashcheck == '-') {
                lastch = readTchar(fp);
            } else {
                Zungetc(dashcheck, fp);
                lastch = firstch;
            }
            skipws(fp);
            target = readTchar(fp);
            skiptoeol(fp);
            addcommand(1, firstch, lastch, (int)(target - firstch));
            break;
        case '0': case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8': case '9':
            Zungetc(command, fp);
            readnum(fp, &firstch);
            skipws(fp);
            readnum(fp, &target);
            skiptoeol(fp);
            addcommand(1, firstch, firstch, (int)(target - firstch));
            break;
        case 'f':
            skiptoeol(fp);
            addcommand(0, 0, 0, 0);
            break;
        case 'b':
            multibyte = 1;
            break;
        case 'u':
            multibyte = 2;
            break;
        case 'h':
            multibyte = 3;
            break;
        case 'j':
            multibyte = 4;
            break;
        case 'g':
            multibyte = 0;
            skipws(fp);
            command = Zgetc(fp);
            switch (command) {
            case '0': charset(0, fp); break;
            case '1': charset(1, fp); break;
            case '2': charset(2, fp); break;
            case '3': charset(3, fp); break;
            case 'l': case 'L':
                skipws(fp);
                gl = Zgetc(fp) - '0';
                skiptoeol(fp);
                break;
            case 'r': case 'R':
                skipws(fp);
                gr = Zgetc(fp) - '0';
                skiptoeol(fp);
                break;
            default:
                skiptoeol(fp);
            }
            break;
        case '\r': case '\n':
            break;
        default:
            skiptoeol(fp);
        }
    }
    Zclose(fp);
}

static void readcontrolfiles(void)
{
    cfnamenode *p;
    for (p = cfilelist; p; p = p->next)
        readcontrol(p->thename);
}

static inchr handlemapping(inchr c)
{
    comnode *cm = commandlist;
    while (cm) {
        if (cm->thecommand && c >= cm->rangelo && c <= cm->rangehi) {
            c += cm->offset;
            while (cm && cm->thecommand) cm = cm->next;
        } else {
            cm = cm->next;
        }
    }
    return c;
}

/* ------------------------------------------------------------------ */
/* Font loading                                                         */

static unsigned hashord(inchr o)
{
    unsigned long u = (unsigned long)o;
    return (unsigned)(u % HASHSIZE);
}

static void storechar(inchr ord, outchr **rows)
{
    unsigned h = hashord(ord);
    fcharnode *n = fchash[h];
    while (n) {
        if (n->ord == ord) { n->thechar = rows; return; }
        n = n->next;
    }
    n = myalloc(sizeof(fcharnode));
    n->ord = ord;
    n->thechar = rows;
    n->next = fchash[h];
    fchash[h] = n;
}

static outchr **findchar(inchr ord)
{
    fcharnode *n = fchash[hashord(ord)];
    while (n) {
        if (n->ord == ord) return n->thechar;
        n = n->next;
    }
    return NULL;
}

/* UTF-8 decoding of font lines, stopping at the first invalid
   sequence.  The decode buffer deliberately persists between calls. */
static outchr decodebuf[MAXLEN + 64];

static int utf8_mbtowc(outchr *p, const unsigned char *s, int n)
{
    static const struct { unsigned char cmask, cval; int shift; long lmask, lval; } tab[] = {
        {0x80, 0x00, 0 * 6, 0x7F, 0},
        {0xE0, 0xC0, 1 * 6, 0x7FF, 0x80},
        {0xF0, 0xE0, 2 * 6, 0xFFFF, 0x800},
        {0xF8, 0xF0, 3 * 6, 0x1FFFFF, 0x10000},
        {0xFC, 0xF8, 4 * 6, 0x3FFFFFF, 0x200000},
        {0xFE, 0xFC, 5 * 6, 0x7FFFFFFF, 0x4000000},
        {0, 0, 0, 0, 0}
    };
    long l;
    int c0, c, nc = 0, i;
    c0 = *s;
    l = c0;
    for (i = 0; tab[i].cmask; i++) {
        nc++;
        if ((c0 & tab[i].cmask) == tab[i].cval) {
            l &= tab[i].lmask;
            if (l < tab[i].lval) return -1;
            *p = (outchr)l;
            return nc;
        }
        if (n <= nc) return -1;
        s++;
        c = (*s ^ 0x80) & 0xFF;
        if (c & 0xC0) return -1;
        l = (l << 6) | c;
    }
    return -1;
}

/* returns -1 on failure (buffer left partially written, not terminated) */
static int utf8_decode_line(outchr *out, const char *in, int n)
{
    const unsigned char *ip = (const unsigned char *)in;
    outchr *op = out;
    while (*ip && n > 0) {
        if (*ip & 0x80) {
            int size = utf8_mbtowc(op, ip, n);
            if (size == -1) return -1;
            op++; ip += size; n -= size;
        } else {
            *op++ = *ip++;
            n--;
        }
    }
    *op = 0;
    return (int)(op - out);
}

static void readfontchar(ZFILE *file, inchr theord)
{
    int row, k;
    char templine[MAXLEN + 2];
    outchr endchar;
    outchr **rows = myalloc(sizeof(outchr *) * charheight);

    for (row = 0; row < charheight; row++) {
        if (myfgets(templine, MAXLEN, file) == NULL)
            templine[0] = '\0';
        utf8_decode_line(decodebuf, templine, MAXLEN);
        k = ostrlen(decodebuf) - 1;
        while (k >= 0 && decodebuf[k] < 128 && isspace(decodebuf[k])) k--;
        if (k >= 0) {
            endchar = decodebuf[k];
            while (k >= 0 && decodebuf[k] == endchar) k--;
        }
        decodebuf[k + 1] = 0;
        rows[row] = myalloc(sizeof(outchr) * (ostrlen(decodebuf) + 1));
        ocopy(rows[row], decodebuf);
    }
    storechar(theord, rows);
}

/* emulate sscanf("%*c%c %d %d %d %d %d %d %d") */
static int parseheader(const char *line, char *hb, int *nums, int maxnums)
{
    const char *p = line;
    int count = 0;
    if (!*p) return 0;
    p++;                       /* %*c */
    if (!*p) return 0;
    *hb = *p++;                /* %c */
    count = 0;
    while (count < maxnums) {
        while (*p && isspace((unsigned char)*p)) p++;
        const char *q = p;
        int neg = 0;
        if (*q == '-' || *q == '+') { neg = (*q == '-'); q++; }
        if (!(*q >= '0' && *q <= '9')) break;
        long v = 0;
        while (*q >= '0' && *q <= '9') { v = v * 10 + (*q - '0'); q++; }
        nums[count++] = (int)(neg ? -v : v);
        p = q;
    }
    return count + 1;
}

static void readfont(void)
{
    ZFILE *fontfile = NULL;
    char *fontpath;
    char magic[5];
    char fileline[MAXLEN + 2];
    char hb = 0;
    int nums[7] = {0, 0, 0, 0, 0, 0, 0};
